"""FIXED harness for the Omnigrok MNIST grokking experiment.

Every constant here is Omnigrok's own
(`Omnigrok/mnist/grokking/mnist-grokking.ipynb`, cell 7), which `ironjr/grokfast`
re-published verbatim as the argparse defaults of `main_mnist.py`:

    train_points 1000 | optimization_steps 100000 | batch_size 200 | loss MSE
    optimizer AdamW    | weight_decay 0.01        | lr 1e-3
    initialization_scale 8.0 | depth 3 | width 200 | activation ReLU | float64

Differences from the notebook, both deliberate:

* the data is held GPU-resident as a tensor instead of going through a
  ``DataLoader`` over a torchvision ``Subset`` -- the notebook's per-item
  ``ToTensor()`` is what makes grokfast's own table report 43.8 ms/iteration for a
  199k-parameter MLP;
* the test accuracy that the metric is read off is computed on the FULL 10000-image
  test split by a separate fixed process, not on the notebook's random 2000-image
  subsample.

The subset the network trains on is ``train_pool[:n_train]``, i.e. exactly
``Subset(MNIST(train=True), range(n_train))`` -- the notebook's own choice.
"""
from __future__ import annotations

import hashlib
import math
import os
from pathlib import Path

import numpy as np
import torch
import torch.nn as nn


def _settings():
    """Loaded lazily and only by the fixed stages.  The settings table is
    verifier-side (the task's configs/mlsb_settings.py); the run script stages a
    root-only copy and names it in MLSB_GROK_SETTINGS for the fixed stages only."""
    path = os.environ.get("MLSB_GROK_SETTINGS")
    if not path:
        raise RuntimeError("MLSB_GROK_SETTINGS is not set: only the fixed stages read the settings")
    import importlib.util
    spec = importlib.util.spec_from_file_location("mlsb_settings", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.SETTINGS

DTYPE = torch.float64

BATCH_SIZE = 200
DEPTH = 3
WIDTH = 200
LR_DEFAULT = 1e-3
WD_DEFAULT = 0.01
CKPTS_PER_DECADE = 12


def opaque_label(setting: str) -> str:
    """A stable, regime-free name for a setting.

    The submitted rule is allowed to specialise per setting -- a schedule may legitimately
    depend on which problem it is on -- but it must not learn *which* regime that is, or a
    rule could branch on a setting by name. The label it sees is therefore a hash
    of the real one: stable across runs and seeds, and carrying nothing about alpha, the
    training-set size or the threshold.
    """
    return "setting-" + hashlib.sha1(("mlsb-grok/" + setting).encode()).hexdigest()[:8]


def data_root() -> Path:
    return Path(os.environ.get("DATA_ROOT", "/data/omnigrok"))


def _load(name: str) -> np.ndarray:
    return np.load(data_root() / name)


def load_pool():
    """(x, y) of the 2000-image training pool, uint8, in raw MNIST order."""
    return _load("train_pool_x.npy"), _load("train_pool_y.npy")


def load_test():
    """The 10000-image test split. Refuses to run where the test split is forbidden."""
    if os.environ.get("MLSB_NO_TEST", "") == "1":
        raise RuntimeError(
            "the test split is not available in this process (MLSB_NO_TEST=1)")
    return _load("test_x.npy"), _load("test_y.npy")


def data_sha256() -> str:
    """One digest over every staged array, in a fixed order."""
    h = hashlib.sha256()
    for name in ("train_pool_x.npy", "train_pool_y.npy", "test_x.npy", "test_y.npy"):
        h.update(np.ascontiguousarray(_load(name)).tobytes())
    return h.hexdigest()


def to_tensors(x: np.ndarray, y: np.ndarray, device):
    """torchvision's ToTensor() convention: uint8 -> float in [0, 1], flattened."""
    xt = torch.from_numpy(np.ascontiguousarray(x)).to(device=device, dtype=DTYPE) / 255.0
    return xt.reshape(len(x), -1), torch.from_numpy(np.ascontiguousarray(y)).to(
        device=device, dtype=torch.long)


def build_model(seed: int, alpha: float, device) -> nn.Module:
    """Omnigrok's depth-3 width-200 ReLU MLP, all parameters scaled by alpha."""
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    layers = [nn.Flatten()]
    for i in range(DEPTH):
        if i == 0:
            layers.append(nn.Linear(784, WIDTH))
            layers.append(nn.ReLU())
        elif i == DEPTH - 1:
            layers.append(nn.Linear(WIDTH, 10))
        else:
            layers.append(nn.Linear(WIDTH, WIDTH))
            layers.append(nn.ReLU())
    mlp = nn.Sequential(*layers).to(device=device, dtype=DTYPE)
    with torch.no_grad():
        for p in mlp.parameters():
            p.data = alpha * p.data
    return mlp


def n_params(model: nn.Module) -> int:
    return sum(p.numel() for p in model.parameters() if p.requires_grad)


def checkpoint_steps(budget: int) -> list:
    """Log-spaced grid, 12 points per decade, always including 0 and the budget."""
    steps = {0, int(budget)}
    k = 0
    while True:
        s = int(round(10.0 ** (k / CKPTS_PER_DECADE)))
        if s > budget:
            break
        steps.add(s)
        k += 1
    return sorted(steps)


class BatchStream:
    """The notebook's ``cycle(DataLoader(shuffle=True))``, made deterministic.

    Each pass draws a fresh permutation of the n training indices and yields it in
    chunks of BATCH_SIZE (the final short chunk included, as DataLoader does by
    default). The stream depends only on the seed, so every update rule sees exactly
    the same batches in the same order.
    """

    def __init__(self, n: int, seed: int, device):
        self.n = n
        self.g = torch.Generator(device="cpu")
        self.g.manual_seed(seed * 1000003 + 17)
        self.device = device
        self._buf = []

    def next_indices(self) -> torch.Tensor:
        if not self._buf:
            perm = torch.randperm(self.n, generator=self.g)
            self._buf = [perm[i:i + BATCH_SIZE] for i in range(0, self.n, BATCH_SIZE)]
        return self._buf.pop(0).to(self.device)


@torch.no_grad()
def accuracy(model: nn.Module, x: torch.Tensor, y: torch.Tensor, chunk: int = 2000) -> float:
    correct = 0
    for i in range(0, len(x), chunk):
        correct += int((model(x[i:i + chunk]).argmax(dim=1) == y[i:i + chunk]).sum())
    return correct / len(x)


@torch.no_grad()
def mse_loss_value(model: nn.Module, x: torch.Tensor, y: torch.Tensor,
                   chunk: int = 2000) -> float:
    eye = torch.eye(10, device=x.device, dtype=DTYPE)
    total = 0.0
    for i in range(0, len(x), chunk):
        out = model(x[i:i + chunk])
        total += float(((out - eye[y[i:i + chunk]]) ** 2).sum())
    return total / (len(x) * 10)


@torch.no_grad()
def weight_norm(model: nn.Module) -> float:
    return math.sqrt(float(sum((p ** 2).sum() for p in model.parameters())))

